1637	chat-f70ef80b-5387-422a-83da-fe212221217a	step-02	read_file	{"path": "D:\\\\LOCAL_Share\\\\Code Projects\\\\boost-python-sql\\\\main.py"}	{"ok": true, "path": "D:\\\\LOCAL_Share\\\\Code Projects\\\\boost-python-sql\\\\main.py", "size": 7122, "tool": "read_file", "sha256": "9adc546bdea642768b02707017b0ae860c27b6f9600dca3ceecc8003566f8acb", "content": "from turbodbc import connect\\n\\n# def connection(server, port, db, user, password):\\n#     return connect(\\n#         connection_string=f'driver=PostgreSQL ANSI;server={server};port={port};database={db};uid={user};pwd={password};')\\n#\\n#\\n# cursor = connection.cursor()\\n# cursor.execute('SELECT relname from pg_stat_user_tables ORDER BY RANDOM() LIMIT 1')\\n# print(cursor.fetchall())\\nimport os\\nimport datetime\\nfrom concurrent.futures import ThreadPoolExecutor\\nfrom turbodbc import connect\\nfrom turbodbc.exceptions import Error\\nfrom kh_network.connect_help import make_connection_string\\n\\nimport credentials\\n\\n# Configuration\\nORIGIN_DB = {\\n    \\"Driver\\": \\"PostgreSQL Unicode\\",\\n    \\"Server\\": \\"kh22.boga-dace.ts.net\\",\\n    \\"Port\\": 15432,\\n    \\"Database\\": \\"polygon_play\\",\\n    \\"Uid\\": \\"postgres\\",\\n    \\"Pwd\\": \\"default\\",\\n}\\nDESTINATION_DB = connect(connection_string=make_connection_string(credentials.CREDS_KH22_FINMO, credentials.TURBOCON_PARAMS))\\n\\nRANGE = (datetime.date(1990, 1, 1), datetime.date.today())\\nMAX_THREADS = 10\\n\\n\\ndef get_connection(db_config):\\n    \\"\\"\\"\\n    Establish a connection using TurboODBC.\\n    \\"\\"\\"\\n    connection_string = \\";\\".join(f\\"{key}={value}\\" for key, value in db_config.items())\\n    return connect(connection_string=connection_string)\\n\\n\\ndef create_partitioned_table(schema, table_name):\\n    \\"\\"\\"\\n    Create a partitioned table in the destination database using TurboODBC.\\n    \\"\\"\\"\\n    with get_connection(DESTINATION_DB) as connection:\\n        cursor = connection.cursor()\\n\\n        # Create main partitioned table\\n        cursor.execute(\\n            f'''\\n            CREATE TABLE IF NOT EXISTS {schema}.\\"{table_name}\\" (\\n                timestamp TIMESTAMP NOT NULL,\\n                open FLOAT8 NOT NULL,\\n                high FLOAT8 NOT NULL,\\n                low FLOAT8 NOT NULL,\\n                close FLOAT8 NOT NULL,\\n                volume INT8,\\n                number INT8,\\n                year INT NOT NULL,\\n                month INT NOT NULL,\\n                PRIMARY KEY (timestamp, year, month)\\n            ) PARTITION BY RANGE (year)\\n            '''\\n        )\\n\\n        # Create year and month partitions\\n        for year in range(RANGE[0].year, RANGE[1].year + 1):\\n            year_partition = f\\"{table_name}_y{year}\\"\\n            cursor.execute(\\n                f\\"\\"\\"\\n                CREATE TABLE IF NOT EXISTS {schema}.\\"{year_partition}\\"\\n                PARTITION OF {schema}.\\"{table_name}\\"\\n                FOR VALUES FROM ({year}) TO ({year + 1})\\n                PARTITION BY RANGE (month)\\n                \\"\\"\\"\\n            )\\n            connection.commit()\\n            for month in range(1, 13):\\n                month_partition = f\\"{year_partition}_m{month:02d}\\"\\n                cursor.execute(\\n                    f\\"\\"\\"\\n                    CREATE TABLE IF NOT EXISTS {schema}.\\"{month_partition}\\"\\n                    PARTITION OF {schema}.\\"{year_partition}\\"\\n                    FOR VALUES FROM ({month}) TO ({month + 1})\\n                    \\"\\"\\"\\n                )\\n\\n\\ndef fetch_data(table_name):\\n    \\"\\"\\"\\n    Fetch data from the source database using TurboODBC.\\n    \\"\\"\\"\\n    with get_connection(ORIGIN_DB) as connection:\\n        cursor = connection.cursor()\\n        cursor.execute(f\\"SELECT * FROM public.{table_name}\\")\\n        data = cursor.fetchall()\\n        return data\\n\\n\\ndef insert_data(schema, table_name, data):\\n    \\"\\"\\"\\n    Insert data into the partitioned table using bind variables in TurboODBC.\\n    \\"\\"\\"\\n    processed_data = [\\n        (\\n            row[0],  # timestamp\\n            row[1],  # open\\n            row[2],  # high\\n            row[3],  # low\\n            row[4],  # close\\n            row[5],  # volume\\n            row[6],  # number\\n            row[0].year,  # year from timestamp\\n            row[0].month,  # month from timestamp\\n        )\\n        for row in data\\n    ]\\n\\n    with get_connection(DESTINATION_DB) as connection:\\n        insert_query = f'''\\n            INSERT INTO {schema}.\\"{table_name}\\" (\\n                timestamp, open, high, low, close, volume, number, year, month\\n            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)\\n        '''\\n        try:\\n            with connection.cursor() as cursor:\\n                cursor.executemany(insert_query, processed_data)\\n                print(f\\"Inserted {len(data)} rows into {schema}.{table_name}.\\")\\n        except Error as e:\\n            print(f\\"Error during data insertion: {e}\\")\\n\\n\\ndef process_table(table_name):\\n    \\"\\"\\"\\n    Full pipeline for processing a single table.\\n    \\"\\"\\"\\n    schema = \\"partitioned_intraday\\"\\n    # schema = \\"public\\"\\n\\n    # Check if table exists\\n    with get_connection(DESTINATION_DB) as connection:\\n        cursor = connection.cursor()\\n        # cursor.execute(\\n        #     f'''\\n        #     CREATE SCHEMA IF NOT EXISTS {schema}\\n        #     '''\\n        # )\\n        cursor.execute(\\n            f\\"\\"\\"\\n            SELECT EXISTS (\\n                SELECT 1\\n                FROM pg_class c\\n                JOIN pg_namespace n ON c.relnamespace = n.oid\\n                WHERE n.nspname = '{schema}' AND c.relname = '{table_name}' AND c.relkind = 'r'\\n            )::BOOLEAN\\n            \\"\\"\\"\\n        )\\n        main_table_exists = int(cursor.fetchone()[0])\\n\\n    # If the main table exists, skip creating it, but ensure partitions are created\\n    if not main_table_exists:\\n        print(f\\"Creating main table: {schema}.{table_name}\\")\\n        create_partitioned_table(schema, table_name)\\n    else:\\n        print(f\\"Main table {schema}.{table_name} already exists. Checking partitions...\\")\\n\\n    # Ensure partitions are created for the table\\n    create_partitioned_table(schema, table_name)\\n    connection.commit()\\n\\n    # Fetch data from origin\\n    data = fetch_data(table_name)\\n\\n    # Insert data into destination\\n    insert_data(schema, table_name, data)\\n    connection.commit()\\n\\n\\ndef get_random_table(filter_str=None):\\n    \\"\\"\\"\\n    Fetch a random table name from the source database.\\n    \\"\\"\\"\\n    with get_connection(ORIGIN_DB) as connection:\\n        cursor = connection.cursor()\\n        if filter_str:\\n            cursor.execute(\\n                f\\"\\"\\"\\n                SELECT tablename\\n                FROM pg_tables\\n                WHERE tablename LIKE '{filter_str}' AND schemaname = 'public'\\n                ORDER BY RANDOM()\\n                LIMIT 1\\n                \\"\\"\\"\\n            )\\n        else:\\n            cursor.execute(\\n                \\"\\"\\"\\n                SELECT tablename\\n                FROM pg_tables\\n                ORDER BY RANDOM()\\n                LIMIT 1\\n                \\"\\"\\"\\n            )\\n        result = cursor.fetchone()\\n        return result[0] if result else None\\n\\n\\ndef main():\\n    \\"\\"\\"\\n    Main driver function.\\n    \\"\\"\\"\\n    ITERATIONS = 1000\\n\\n    with ThreadPoolExecutor(max_workers=MAX_THREADS) as executor:\\n        for _ in range(ITERATIONS):\\n            table_name = get_random_table(\\"%_1minute\\")\\n            executor.submit(process_table, table_name)\\n\\n\\nif __name__ == \\"__main__\\":\\n    main()\\n", "end_line": 223, "start_line": 1, "total_lines": 223}	f	2026-09-19 20:31:35.966145-04
