53	chat-a75c8e0b-516d-4e77-932e-0ee779c79575	step-03	read_file	{"path": "D:\\\\LOCAL_Share\\\\Code Projects\\\\goBackend\\\\internal\\\\handlers\\\\tables.go"}	{"ok": true, "path": "D:\\\\LOCAL_Share\\\\Code Projects\\\\goBackend\\\\internal\\\\handlers\\\\tables.go", "size": 2024, "tool": "read_file", "sha256": "552afeb72747bc3a38313cdd3ae305102bf97f374278375290a0bb47a2acf6a3", "content": "package handlers\\n\\nimport (\\n\\t\\"context\\"\\n\\t\\"encoding/json\\"\\n\\t\\"fmt\\"\\n\\t\\"net/http\\"\\n\\t\\"strconv\\"\\n\\t\\"time\\"\\n)\\n\\ntype TableInfo struct {\\n\\tSchema string `json:\\"schema\\"`\\n\\tName   string `json:\\"name\\"`\\n}\\n\\nfunc (a *App) GetTables(w http.ResponseWriter, r *http.Request) {\\n\\tif r.Method != http.MethodGet {\\n\\t\\thttp.Error(w, \\"method not allowed\\", http.StatusMethodNotAllowed)\\n\\t\\treturn\\n\\t}\\n\\n\\tschema := r.URL.Query().Get(\\"schema\\")\\n\\tname := r.URL.Query().Get(\\"name\\")\\n\\tlimitStr := r.URL.Query().Get(\\"limit\\")\\n\\n\\tctx, cancel := context.WithTimeout(r.Context(), 5*time.Second)\\n\\tdefer cancel()\\n\\n\\tquery := `\\n\\t\\tSELECT table_schema, table_name\\n\\t\\tFROM information_schema.tables\\n\\t\\tWHERE table_type = 'BASE TABLE'\\n\\t`\\n\\n\\targs := []any{}\\n\\targIndex := 1\\n\\n\\tif schema != \\"\\" {\\n\\t\\tquery += \\" AND table_schema = $\\" + itoa(argIndex)\\n\\t\\targs = append(args, schema)\\n\\t\\targIndex++\\n\\t}\\n\\n\\tif name != \\"\\" {\\n\\t\\tquery += \\" AND table_name ILIKE $\\" + itoa(argIndex)\\n\\t\\targs = append(args, \\"%\\"+name+\\"%\\")\\n\\t\\targIndex++\\n\\t}\\n\\n\\tif limitStr != \\"\\" {\\n\\t\\tlimit, err := strconv.Atoi(limitStr)\\n\\t\\tif err != nil || limit <= 0 {\\n\\t\\t\\thttp.Error(w, \\"invalid limit\\", http.StatusBadRequest)\\n\\t\\t\\treturn\\n\\t\\t}\\n\\n\\t\\tquery += \\" ORDER BY random()\\"\\n\\t\\tquery += \\" LIMIT $\\" + itoa(argIndex)\\n\\t\\targs = append(args, limit)\\n\\t} else {\\n\\t\\tquery += \\" ORDER BY table_schema, table_name\\"\\n\\t}\\n\\n\\trows, err := a.DB.Query(ctx, query, args...)\\n\\tif err != nil {\\n\\t\\thttp.Error(w, err.Error(), http.StatusInternalServerError)\\n\\t\\treturn\\n\\t}\\n\\tdefer rows.Close()\\n\\n\\ttables := make([]TableInfo, 0)\\n\\n\\tfor rows.Next() {\\n\\t\\tvar t TableInfo\\n\\n\\t\\tif err := rows.Scan(&t.Schema, &t.Name); err != nil {\\n\\t\\t\\thttp.Error(w, err.Error(), http.StatusInternalServerError)\\n\\t\\t\\treturn\\n\\t\\t}\\n\\n\\t\\ttables = append(tables, t)\\n\\t}\\n\\n\\tif err := rows.Err(); err != nil {\\n\\t\\thttp.Error(w, err.Error(), http.StatusInternalServerError)\\n\\t\\treturn\\n\\t}\\n\\n\\tw.Header().Set(\\"Content-Type\\", \\"application/json\\")\\n\\tif err := json.NewEncoder(w).Encode(tables); err != nil {\\n\\t\\thttp.Error(w, err.Error(), http.StatusInternalServerError)\\n\\t\\treturn\\n\\t}\\n}\\n\\nfunc itoa(i int) string {\\n\\treturn fmt.Sprintf(\\"%d\\", i)\\n}\\n", "end_line": 99, "start_line": 1, "total_lines": 99}	f	2026-09-16 19:33:14.976724-04
