1657	chat-f70ef80b-5387-422a-83da-fe212221217a	step-03	read_file	{"path": "D:\\\\LOCAL_Share\\\\Code Projects\\\\boost-python-sql\\\\pipeline_update_tickers\\\\help_connect.py"}	{"ok": true, "path": "D:\\\\LOCAL_Share\\\\Code Projects\\\\boost-python-sql\\\\pipeline_update_tickers\\\\help_connect.py", "size": 5933, "tool": "read_file", "sha256": "075e3223671587ca414452aa0a2fa2728b09d0508df42e3cb441df2879dc960d", "content": "from rich import print\\nfrom rich.console import Console\\nimport numpy as np\\nfrom turbodbc import connect, make_options\\nimport datetime\\nfrom munch import Munch\\nfrom psycopg import sql\\n\\nvariables = Munch(RANGE=(datetime.date(1990, 1, 1), datetime.date.today()), MAX_THREADS=10, origin_schema='public',\\n                  destination_schema='partitioned_intraday')\\ncon = Console()\\n\\n\\ndef get_connection(db_config):\\n    \\"\\"\\"\\n    Establish a connection using TurboODBC.\\n    \\"\\"\\"\\n    connection_string = \\";\\".join(f\\"{key}={value}\\" for key, value in db_config.items())\\n    return connect(connection_string=connection_string, turbodbc_options=make_options(autocommit=True))\\n\\n\\ncurrent_data_origin_db = get_connection(\\n    {\\n        \\"Driver\\": \\"PostgreSQL Unicode\\",\\n        \\"Server\\": \\"kh22.boga-dace.ts.net\\",\\n        \\"Port\\": 15432,\\n        \\"Database\\": \\"polygon_play\\",\\n        \\"Uid\\": \\"postgres\\",\\n        \\"Pwd\\": \\"default\\",\\n    }\\n)\\n\\nrandom_fetch_db = get_connection(\\n    {\\n        \\"Driver\\": \\"PostgreSQL Unicode\\",\\n        \\"Server\\": \\"kh22.boga-dace.ts.net\\",\\n        \\"Port\\": 15432,\\n        \\"Database\\": \\"defact\\",\\n        \\"Uid\\": \\"postgres\\",\\n        \\"Pwd\\": \\"default\\",\\n    }\\n)\\n\\ndestination_target_db = get_connection(\\n    {\\n        \\"Driver\\": \\"PostgreSQL Unicode\\",\\n        \\"Server\\": \\"khzz.boga-dace.ts.net\\",\\n        \\"Port\\": 25432,\\n        \\"Database\\": \\"stocks_api\\",\\n        \\"Uid\\": \\"kernel_hermit\\",\\n        \\"Pwd\\": \\"Adjunct45\\",\\n    }\\n)\\n\\ntable_structure_assist = '''\\n                timestamp TIMESTAMP NOT NULL,\\n                open FLOAT8,\\n                high FLOAT8,\\n                low FLOAT8,\\n                close FLOAT8,\\n                volume INT8,\\n                number INT8,\\n                year INT NOT NULL,\\n                month INT NOT NULL,\\n                PRIMARY KEY (timestamp, year, month)\\n'''\\n\\ncolumn_transpose_transfer_map = Munch(\\n    t='timestamp',\\n    o='open',\\n    h='high',\\n    l='low',\\n    c='close',\\n    v='volume',\\n    n='number',\\n    m='month',\\n    y='year'\\n)\\ncolumn_transmute_dictionary = column_transpose_transfer_map\\ncolumn_transform_transfigured_mapping = [j for i, j in column_transpose_transfer_map.items()]\\ncolumns_list = sql.SQL(\\", \\").join(map(sql.Identifier, column_transform_transfigured_mapping))\\nplaceholders = sql.SQL(\\", \\").join(sql.Placeholder() * len(column_transform_transfigured_mapping))\\n\\n\\ndef create_partitioned_table(table_name, table_structure, connection_cursor, schema=\\"public\\"):\\n    query = '''\\n        CREATE TABLE IF NOT EXISTS {}.\\"{}\\" (\\n            {}\\n        ) PARTITION BY RANGE (year)\\n    '''.format(schema, table_name, table_structure)\\n\\n    connection_cursor.execute(query)\\n\\n    for year in range(variables.RANGE[0].year, variables.RANGE[1].year + 1):\\n        year_partition = f\\"{table_name}_y{year}\\"\\n        connection_cursor.execute(\\n            f\\"\\"\\"\\n            CREATE TABLE IF NOT EXISTS {schema}.\\"{year_partition}\\"\\n            PARTITION OF {schema}.\\"{table_name}\\"\\n            FOR VALUES FROM ({year}) TO ({year + 1})\\n            PARTITION BY RANGE (month)\\n            \\"\\"\\"\\n        )\\n        for month in range(1, 13):\\n            month_partition = f\\"{year_partition}_m{month:02d}\\"\\n            connection_cursor.execute(\\n                f\\"\\"\\"\\n                CREATE TABLE IF NOT EXISTS {schema}.\\"{month_partition}\\"\\n                PARTITION OF {schema}.\\"{year_partition}\\"\\n                FOR VALUES FROM ({month}) TO ({month + 1})\\n                \\"\\"\\"\\n            )\\n\\n\\ndef get_random_table(n=1):\\n    with random_fetch_db.cursor() as cur:\\n        cur.execute(\\"SELECT ticker from company_info WHERE type IN ('CS', 'ETF') ORDER BY RANDOM() LIMIT ?\\", [n])\\n        r = cur.fetchall()\\n        return [a[0] for a in r]\\n\\n\\ndef verify_table(table_name: str, schema: str, connection):\\n    \\"\\"\\"\\n    Checks if a table with the given name and schema exists in the PostgreSQL database.\\n\\n    Args:\\n        table_name (str): The name of the table to check.\\n        schema (str): The schema where the table should exist.\\n        connection: A turbodbc connection object.\\n\\n    Returns:\\n        bool: True if the table exists, False otherwise.\\n    \\"\\"\\"\\n    query = '''\\n        SELECT EXISTS (\\n            SELECT 1\\n            FROM information_schema.tables\\n            WHERE table_name = ?\\n              AND table_schema = ?\\n        )\\n    '''\\n    with connection.cursor() as cursor:\\n        cursor.execute(query, [table_name, schema])\\n        result = cursor.fetchone()\\n        return int(result[0])\\n\\n\\ndef main_script(n=1):\\n    for item in get_random_table(n):\\n        table_name = f'{item}_1minute'\\n        print(verify_table(table_name, 'public', current_data_origin_db))\\n        con.print(f'[yellow]Creating, Partitioning, and Populating [bold]{table_name}[/bold][/yellow]')\\n        destination_target_db.autocommit = True\\n        create_partitioned_table(table_name, table_structure_assist, destination_target_db.cursor(),\\n                                 schema=variables.destination_schema)\\n        destination_target_db.commit()\\n        with current_data_origin_db.cursor() as cursor:\\n            execute = cursor.execute('SELECT * FROM {}.\\"{}\\"'.format(variables.origin_schema, table_name))\\n            columns = [desc[0] for desc in cursor.description]\\n            data = np.array(execute.fetchall())\\n        with destination_target_db.cursor() as cursor:\\n            column_indices = [columns.index(col) for col in column_transform_transfigured_mapping]\\n            data = data[:, column_indices].tolist()\\n            query = f'INSERT INTO {variables.destination_schema}.\\"{table_name}\\" ({\\", \\".join(column_transform_transfigured_mapping)}) VALUES ({\\", \\".join(\\"?\\" * len(column_transform_transfigured_mapping))})'\\n            cursor.executemany(query, data)\\n            destination_target_db.commit()\\n\\n\\nif __name__ == \\"__main__\\":\\n    main_script()\\n", "end_line": 170, "start_line": 1, "total_lines": 170}	f	2026-09-19 20:34:49.919132-04
