1658	chat-f70ef80b-5387-422a-83da-fe212221217a	step-03	read_file	{"path": "D:\\\\LOCAL_Share\\\\Code Projects\\\\boost-python-sql\\\\pipeline_update_tickers\\\\step_ff_main.py"}	{"ok": true, "path": "D:\\\\LOCAL_Share\\\\Code Projects\\\\boost-python-sql\\\\pipeline_update_tickers\\\\step_ff_main.py", "size": 4229, "tool": "read_file", "sha256": "406c19f0f8ae9bf40fe18ba477d319052444fcb3fd8e3351d9ef449f369e1c71", "content": "# main.py\\nimport logging\\nimport time\\n\\nimport psycopg\\nimport threading\\nfrom concurrent.futures import ThreadPoolExecutor\\nfrom datetime import datetime, timedelta\\nfrom step_01_fetch import run_fetch_batch\\nfrom step_02_iterate_variables import generate_date_range, split_dates\\nfrom step_03_insert_to_db import check_table_exists, execute_schema, db_writer_thread\\nfrom shared_queue import data_queue\\nfrom kh_data.mong_access import *\\nfrom porting_3step import *\\n\\nlogging.basicConfig(level=logging.INFO)\\nlogger = logging.getLogger(__name__)\\n\\n\\ndef date_intervals(final=datetime.today(), first=datetime(1900, 1, 1)):\\n    end_date = final\\n    start_date = end_date - timedelta(days=6 * 30)  # Approximation of 6 months as 30 days per month\\n\\n    # Generate list of date ranges\\n    date_ranges = []\\n    while end_date > first:\\n        date_ranges.append([start_date, end_date])\\n        end_date = start_date - timedelta(days=1)\\n        start_date = end_date - timedelta(days=6 * 30)\\n\\n    return date_ranges\\n\\n\\ndef main(ranger):\\n    # Configuration\\n    api_url_template = \\"https://financialmodelingprep.com/api/v3/historical-chart/1min/{}?from={}&to={}&apikey={}\\"\\n    schema = \\"finmo_indexes\\"\\n    api_key = API_KMONGER.get(alias='finmo')[0]['key']\\n    ticker = \\"%5EIXIC\\"\\n    table_name = \\"bulk_indexes\\"\\n\\n    # Date Range\\n    print(ranger)\\n    start_date = ranger[0]\\n    end_date = ranger[1]\\n\\n    # Number of API worker threads\\n    num_workers = 5\\n    db_conn = CREDENTIALS_MONGER.get(name='khzz_stocks_api')[0]\\n    # Database credentials\\n    db_config = {\\n        \\"dbname\\": db_conn['Database'],\\n        \\"user\\": db_conn['Uid'],\\n        \\"password\\": db_conn['Pwd'],\\n        \\"host\\": db_conn['Server'],\\n        \\"port\\": db_conn['Port'],\\n    }\\n\\n    try:\\n        # Connect to PostgreSQL\\n        conn = psycopg.connect(**db_config)\\n        logger.info(\\"Connected to PostgreSQL.\\")\\n\\n        # Ensure schema and table exist\\n        with conn as conn:\\n            if not check_table_exists(conn, schema, table_name):\\n                logger.info(f\\"Table {schema}.{table_name} does not exist. Creating it.\\")\\n                execute_schema(conn, schema=schema, table_name=table_name)\\n                logger.info(f\\"Table {schema}.{table_name} created.\\")\\n            else:\\n                logger.info(f\\"Table {schema}.{table_name} exists.\\")\\n\\n            # Launch the database writer in a separate thread\\n\\n            # Generate dates and split into batches\\n            all_dates = list(generate_date_range(start_date, end_date))\\n            date_batches = split_dates(all_dates, num_workers)\\n            writer_thread = threading.Thread(\\n                target=db_writer_thread,\\n                args=(conn, schema, table_name),\\n                daemon=False\\n            )\\n            writer_thread.start()\\n            # Use a ThreadPoolExecutor for API fetchers\\n            with ThreadPoolExecutor(max_workers=num_workers) as executor:\\n                for batch in date_batches:\\n                    executor.submit(\\n                        run_fetch_batch,\\n                        batch,\\n                        api_url_template,\\n                        ticker,\\n                        api_key\\n                    )\\n\\n            # Wait for all API results to be placed in the queue\\n            # Then wait for the queue to drain\\n            data_queue.join()\\n\\n            logger.info(\\"All data fetched and queued. Waiting for DB writer to finish...\\")\\n\\n            # Optionally, you can add more graceful shutdown logic here\\n            # e.g., sending a sentinel item into the queue to indicate no more data.\\n\\n    except Exception as e:\\n        logger.error(f\\"Error in main: {e}\\")\\n    finally:\\n        # with conn as conn:\\n        #     remove_duplicates(conn, schema, table_name)\\n        # We can optionally wait for a brief moment for final writes\\n        threading.Event().wait(20.0)\\n\\n        # Close the DB connection\\n    conn.close()\\n    logger.info(\\"PostgreSQL connection closed.\\")\\n\\n\\nif __name__ == \\"__main__\\":\\n    for r in date_intervals():\\n        main(r)\\n        print('iteration done, waiting 80 seconds')\\n        time.sleep(80)\\n", "end_line": 121, "start_line": 1, "total_lines": 121}	f	2026-09-19 20:34:49.951559-04
