1659	chat-f70ef80b-5387-422a-83da-fe212221217a	step-03	read_file	{"path": "D:\\\\LOCAL_Share\\\\Code Projects\\\\boost-python-sql\\\\pipeline_update_tickers\\\\step_01_fetch.py"}	{"ok": true, "path": "D:\\\\LOCAL_Share\\\\Code Projects\\\\boost-python-sql\\\\pipeline_update_tickers\\\\step_01_fetch.py", "size": 3908, "tool": "read_file", "sha256": "cde60cf37f5002f0349d677a3288141231ed9b6c7799f0a10f08e1593d884a92", "content": "import asyncio\\nimport json\\nimport httpx\\nimport logging\\n\\nimport pandas as pd\\nfrom shared_queue import data_queue\\n\\nlogger = logging.getLogger(__name__)\\n\\n# Constants\\nREQUEST_DELAY = 0.01  # 1/100 second delay between requests\\nWAITING = False\\n\\n\\nasync def worker(worker_id, batches, delay, insert_func, conn, schema, table_name):\\n    \\"\\"\\"\\n    A worker that processes batches of URLs, inserting them into the database.\\n    \\"\\"\\"\\n    for batch_idx, batch in enumerate(batches):\\n        logger.info(f\\"Worker {worker_id} processing batch {batch_idx + 1}/{len(batches)}...\\")\\n\\n        # Insert the current batch into the database\\n        await insert_func(conn, schema, table_name, batch)\\n\\n        # Wait for the specified delay before processing the next batch\\n        if batch_idx < len(batches) - 1:  # Avoid waiting after the last batch\\n            logger.info(f\\"Worker {worker_id} waiting {delay} seconds before next batch...\\")\\n            await asyncio.sleep(delay)\\n\\n\\nasync def fetch_data_async(session, url, max_retries=3, timeout_seconds=30, retry_delay=60):\\n    \\"\\"\\"\\n    Fetch JSON data from the given URL asynchronously with timeout and retry logic.\\n    \\"\\"\\"\\n    retries = 0\\n    while retries < max_retries:\\n        try:\\n            # Introduce a delay before each request\\n            await asyncio.sleep(REQUEST_DELAY)\\n\\n            response = await session.get(url, timeout=httpx.Timeout(timeout_seconds))\\n\\n            # Handle rate-limiting response\\n            if response.status_code == 429:\\n                logger.warning(f\\"Rate limit hit for URL {url}. Retrying after {retry_delay} seconds.\\")\\n                await asyncio.sleep(retry_delay)\\n                retries += 1\\n                continue\\n\\n            # Handle non-200 responses\\n            if response.status_code != 200:\\n                logger.warning(f\\"Non-200 response: {response.status_code} for URL {url}\\")\\n                return None\\n\\n            # Return JSON response if successful\\n            return response.json()\\n\\n        except (httpx.RequestError, httpx.TimeoutException) as e:\\n            retries += 1\\n            logger.error(f\\"Error fetching {url} (attempt {retries}/{max_retries}): {e}\\")\\n            if retries < max_retries:\\n                retry_wait = retry_delay * retries\\n                logger.info(f\\"Retrying in {retry_wait} seconds...\\")\\n                await asyncio.sleep(retry_wait)\\n\\n    # After max retries, return None\\n    logger.error(f\\"Failed to fetch {url} after {max_retries} attempts.\\")\\n    return None\\n\\n\\nasync def fetch_batch_async(batch_dates, api_url_template, ticker, api_key):\\n    \\"\\"\\"\\n    Fetch data for all dates in a batch using httpx.AsyncClient with timeout and retry.\\n    \\"\\"\\"\\n    async with httpx.AsyncClient() as session:\\n        tasks = {\\n            asyncio.create_task(fetch_data_async(session, api_url_template.format(ticker, date, api_key))): date\\n            for date in batch_dates\\n        }\\n\\n        # Process tasks as they complete\\n        for completed_task in asyncio.as_completed(tasks):\\n            date = tasks[completed_task]\\n            try:\\n                result = await completed_task\\n                if result is not None:\\n                    print(pd.DataFrame(result))  # Process the result\\n                    data_queue.put((date, ticker, json.dumps(result)))\\n                else:\\n                    logger.warning(f\\"No result for {date}.\\")\\n            except Exception as e:\\n                logger.error(f\\"Error processing {date}: {e}\\")\\n\\n\\ndef run_fetch_batch(batch_dates, api_url_template, ticker, api_key):\\n    \\"\\"\\"\\n    Synchronous wrapper to run the async fetch in a separate thread.\\n    \\"\\"\\"\\n    loop = asyncio.new_event_loop()\\n    asyncio.set_event_loop(loop)\\n    loop.run_until_complete(fetch_batch_async(batch_dates, api_url_template, ticker, api_key))\\n    loop.close()\\n", "end_line": 103, "start_line": 1, "total_lines": 103}	f	2026-09-19 20:34:49.984544-04
