1661	chat-f70ef80b-5387-422a-83da-fe212221217a	step-03	read_file	{"path": "D:\\\\LOCAL_Share\\\\Code Projects\\\\boost-python-sql\\\\pipeline_update_tickers\\\\step_03_insert_to_db.py"}	{"ok": true, "path": "D:\\\\LOCAL_Share\\\\Code Projects\\\\boost-python-sql\\\\pipeline_update_tickers\\\\step_03_insert_to_db.py", "size": 3375, "tool": "read_file", "sha256": "028b4ecfc6b5fadac9c41bbd0270b46144d207f276112f9866819eef6fe0ffeb", "content": "# step_03_db_writer.py\\nimport logging\\nimport psycopg\\nimport threading\\nfrom shared_queue import data_queue\\nfrom psycopg import sql\\n\\nlogger = logging.getLogger(__name__)\\n\\n\\ndef check_table_exists(conn, schema, table_name):\\n    \\"\\"\\"\\n    Check if the table exists in the given schema.\\n    \\"\\"\\"\\n    query = '''\\n    SELECT EXISTS (\\n        SELECT 1\\n        FROM information_schema.tables\\n        WHERE table_schema = %s AND table_name = %s\\n    );\\n    '''\\n    with conn.cursor() as cur:\\n        cur.execute(query, (schema, table_name))\\n        return cur.fetchone()[0]\\n\\n\\ndef execute_schema(conn, schema, table_name):\\n    \\"\\"\\"\\n    Create the schema (if not exists) and table (if not exists).\\n    Works reliably in psycopg3 without a DO $$ block.\\n    \\"\\"\\"\\n    create_sql = sql.SQL(\\n        \\"\\"\\"\\n        CREATE SCHEMA IF NOT EXISTS {schema_ident};\\n        CREATE TABLE IF NOT EXISTS {schema_ident}.{table_ident} (\\n            id SERIAL PRIMARY KEY,\\n            date DATE NOT NULL,\\n            ticker TEXT NOT NULL,\\n            response JSONB NOT NULL\\n        );\\n        \\"\\"\\"\\n    ).format(\\n        schema_ident=sql.Identifier(schema),\\n        table_ident=sql.Identifier(table_name),\\n    )\\n\\n    try:\\n        with conn.cursor() as cur:\\n            cur.execute(create_sql)\\n        conn.commit()\\n        logger.info(f\\"Schema '{schema}' and table '{table_name}' ensured.\\")\\n    except Exception as e:\\n        logger.error(f\\"Error ensuring schema and table: {e}\\")\\n        raise\\n\\n\\ndef batch_insert_into_table(conn, schema, table_name, data_list):\\n    \\"\\"\\"\\n    Batch insert multiple rows into the table.\\n    \\"\\"\\"\\n    with conn.cursor() as cur:\\n        query = f'INSERT INTO \\"{schema}\\".\\"{table_name}\\" (date, ticker, response) VALUES (%s, %s, %s)'\\n        cur.executemany(query, data_list)\\n    conn.commit()\\n\\n\\ndef db_writer_thread(conn, schema, table_name):\\n    \\"\\"\\"\\n    Continuously consume from the queue and write to the database.\\n    \\"\\"\\"\\n    while True:\\n        # Wait until the queue has data, then pull items\\n        # We can grab up to a batch size in one go if desired.\\n        # Or simply grab everything that’s in the queue at once.\\n        items_to_write = []\\n        while not data_queue.empty():\\n            item = data_queue.get()\\n            items_to_write.append(item)\\n            data_queue.task_done()\\n\\n        if items_to_write:\\n            try:\\n                batch_insert_into_table(conn, schema, table_name, items_to_write)\\n                logger.info(f\\"Inserted {len(items_to_write)} rows into {schema}.{table_name}.\\")\\n            except Exception as e:\\n                logger.error(f\\"Error writing to DB: {e}\\")\\n\\n        # Sleep briefly to avoid hot-looping\\n        threading.Event().wait(0.5)\\n\\n\\nasync def insert_urls_to_db(conn, schema, table_name, urls):\\n    \\"\\"\\"\\n    Insert a list of URLs into the specified table asynchronously.\\n    \\"\\"\\"\\n    try:\\n        with conn.cursor() as cur:\\n            query = f'''\\n            INSERT INTO \\"{schema}\\".\\"{table_name}\\" (url)\\n            VALUES (%s);\\n            '''\\n            cur.executemany(query, [(url,) for url in urls])\\n        conn.commit()\\n        print(f\\"Inserted {len(urls)} URLs into {schema}.{table_name}.\\")\\n    except Exception as e:\\n        conn.rollback()\\n        print(f\\"Error inserting URLs into the database: {e}\\")\\n", "end_line": 107, "start_line": 1, "total_lines": 107}	f	2026-09-19 20:35:07.5203-04
