1662	chat-f70ef80b-5387-422a-83da-fe212221217a	step-03	read_file	{"path": "D:\\\\LOCAL_Share\\\\Code Projects\\\\boost-python-sql\\\\pipeline_update_tickers\\\\porting_3step.py"}	{"ok": true, "path": "D:\\\\LOCAL_Share\\\\Code Projects\\\\boost-python-sql\\\\pipeline_update_tickers\\\\porting_3step.py", "size": 4437, "tool": "read_file", "sha256": "5388b9d2b907eba8b6ee8567f2a30fc6a297eddbb47ee95a5bfa951bff634a25", "content": "import psycopg\\nfrom psycopg import sql\\nimport logging\\n\\n#step 1 - clear duplicate lines\\n#step 2 - prepare and move data to new structure/table/db/schema\\n#step 3 - create new partitioned table and populate\\n# Configure logging\\nlogging.basicConfig(level=logging.INFO)\\nlogger = logging.getLogger(__name__)\\n\\n# Database configuration\\ndb_config = {\\n    \\"dbname\\": \\"your_database\\",\\n    \\"user\\": \\"your_user\\",\\n    \\"password\\": \\"your_password\\",\\n    \\"host\\": \\"localhost\\",\\n    \\"port\\": 5432,\\n}\\n\\n# Old and new schema/table configurations\\nold_schema = \\"finmo_indexes\\"\\nold_table = \\"NASDAQ\\"\\nnew_schema = \\"processed_data\\"\\nnew_table = \\"ticker_1min\\"\\n\\n\\ndef remove_duplicates(conn, schema, table_name, key_as=('date', 'ticker')):\\n    \\"\\"\\"\\n    Ensure there are no duplicate rows for a combination of (date, ticker).\\n    \\"\\"\\"\\n    group_by_columns = sql.SQL(\\", \\").join(map(sql.Identifier, key_as))\\n\\n    query = sql.SQL('''\\n        DELETE FROM {schema}.{table_name}\\n        WHERE ctid NOT IN (\\n            SELECT min(ctid)\\n            FROM {schema}.{table_name}\\n            GROUP BY {group_by_columns}\\n        );\\n    ''').format(\\n        schema=sql.Identifier(schema),\\n        table_name=sql.Identifier(table_name),\\n        group_by_columns=group_by_columns\\n    )\\n\\n    try:\\n        with conn.cursor() as cur:\\n            cur.execute(query)\\n        conn.commit()\\n        logger.info(f\\"Duplicates removed from {schema}.{table_name} using keys: {key_as}.\\")\\n    except Exception as e:\\n        logger.error(f\\"Error removing duplicates: {e}\\")\\n        raise\\n\\n\\ndef create_new_table(conn, schema, table_name):\\n    \\"\\"\\"\\n    Create the new schema and table for processed data.\\n    \\"\\"\\"\\n    create_schema_query = sql.SQL(\\"CREATE SCHEMA IF NOT EXISTS {schema};\\").format(\\n        schema=sql.Identifier(schema)\\n    )\\n    create_table_query = sql.SQL(\\"\\"\\"\\n        CREATE TABLE IF NOT EXISTS {schema}.{table_name} (\\n            id SERIAL PRIMARY KEY,\\n            ticker TEXT NOT NULL,\\n            date DATE NOT NULL,\\n            open NUMERIC,\\n            high NUMERIC,\\n            low NUMERIC,\\n            close NUMERIC,\\n            volume NUMERIC,\\n            other JSONB\\n        );\\n    \\"\\"\\").format(\\n        schema=sql.Identifier(schema),\\n        table_name=sql.Identifier(table_name),\\n    )\\n    with conn.cursor() as cur:\\n        cur.execute(create_schema_query)\\n        cur.execute(create_table_query)\\n    conn.commit()\\n    logger.info(f\\"Schema '{schema}' and table '{table_name}' created or already exist.\\")\\n\\n\\ndef transform_and_insert_data(conn, old_schema, old_table, new_schema, new_table):\\n    \\"\\"\\"\\n    Extract fields from the 'response' JSONB column and insert into the new table.\\n    \\"\\"\\"\\n    insert_query = sql.SQL(\\"\\"\\"\\n        INSERT INTO {new_schema}.{new_table} (\\n            ticker, date, open, high, low, close, volume, other\\n        )\\n        SELECT\\n            ticker,\\n            (response->>'date')::DATE AS date,\\n            (response->>'open')::NUMERIC AS open,\\n            (response->>'high')::NUMERIC AS high,\\n            (response->>'low')::NUMERIC AS low,\\n            (response->>'close')::NUMERIC AS close,\\n            (response->>'volume')::NUMERIC AS volume,\\n            response - 'date' - 'open' - 'high' - 'low' - 'close' - 'volume' AS other\\n        FROM {old_schema}.{old_table};\\n    \\"\\"\\").format(\\n        old_schema=sql.Identifier(old_schema),\\n        old_table=sql.Identifier(old_table),\\n        new_schema=sql.Identifier(new_schema),\\n        new_table=sql.Identifier(new_table),\\n    )\\n    with conn.cursor() as cur:\\n        cur.execute(insert_query)\\n    conn.commit()\\n    logger.info(f\\"Data transformed and inserted into {new_schema}.{new_table}.\\")\\n\\n\\ndef main():\\n    try:\\n        # Connect to PostgreSQL\\n        conn = psycopg.connect(**db_config)\\n        logger.info(\\"Connected to PostgreSQL.\\")\\n\\n        # Remove duplicates in the old table\\n        remove_duplicates(conn, old_schema, old_table)\\n\\n        # Create the new schema and table\\n        create_new_table(conn, new_schema, new_table)\\n\\n        # Transform and insert data\\n        transform_and_insert_data(conn, old_schema, old_table, new_schema, new_table)\\n\\n    except Exception as e:\\n        logger.error(f\\"An error occurred: {e}\\")\\n    finally:\\n        conn.close()\\n        logger.info(\\"PostgreSQL connection closed.\\")\\n\\n\\nif __name__ == \\"__main__\\":\\n    main()\\n", "end_line": 140, "start_line": 1, "total_lines": 140}	f	2026-09-19 20:35:07.554282-04
