n.routes {\\n  width: 100%;\\n  border-collapse: collapse;\\n  font-size: 0.85rem;\\n}\\n\\n.routes th {\\n  text-align: left;\\n  font-weight: 500;\\n  color: var(--text-dim);\\n  font-size: 0.75rem;\\n  text-transform: uppercase;\\n  letter-spacing: 0.04em;\\n  padding: 0.4rem 0.5rem;\\n  border-bottom: 1px solid var(--border);\\n}\\n\\n.routes td {\\n  padding: 0.4rem 0.5rem;\\n  border-bottom: 1px solid var(--border);\\n}\\n\\n.routes tr:last-child td {\\n  border-bottom: none;\\n}\\n\\n.mod {\\n  color: var(--text-dim);\\n  font-family: var(--font-mono);\\n  font-size: 0.8rem;\\n}\\n\\n.method {\\n  font-family: var(--font-mono);\\n  font-size: 0.75rem;\\n  font-weight: 600;\\n  padding: 1px 5px;\\n  border-radius: 3px;\\n}\\n\\n.method.get {\\n  color: var(--success);\\n  background: rgba(78, 203, 113, 0.1);\\n}\\n\\n.method.post {\\n  color: var(--accent);\\n  background: rgba(91, 141, 239, 0.1);\\n}\\n\\n.method.put {\\n  color: var(--warning);\\n  background: rgba(240, 184, 73, 0.1);\\n}\\n\\n.method.delete {\\n  color: var(--error);\\n  background: rgba(239, 91, 91, 0.1);\\n}\\n\\n.path {\\n  font-family: var(--font-mono);\\n  font-size: 0.8rem;\\n}\\n</style>\\n", "end_line": 119, "start_line": 1, "total_lines": 119}	t	2026-09-19 12:56:29.246646-04
1665	chat-f70ef80b-5387-422a-83da-fe212221217a	step-03	read_file	{"path": "D:\\\\LOCAL_Share\\\\Code Projects\\\\boost-python-sql\\\\restart_update_tickers\\\\main.py"}	{"ok": true, "path": "D:\\\\LOCAL_Share\\\\Code Projects\\\\boost-python-sql\\\\restart_update_tickers\\\\main.py", "size": 8025, "tool": "read_file", "sha256": "6a83443cc6847aad982f2a5387459dd9bdc7cbb03e06bd44df3d60e2f667b592", "content": "# main.py\\nimport logging\\nimport time\\nimport json\\nimport httpx\\nimport pandas as pd\\nimport psycopg\\nimport asyncio\\nimport json\\nfrom datetime import datetime, timedelta\\nfrom kh_data.mong_access import *\\nfrom step_03_insert_to_db import *\\nfrom geta_ticker import get\\nfrom color_logs import color_logs\\nimport holidays\\nimport dates_from_db\\nimport gen_var\\nfrom kh_data.strings_theory import shorterns\\n\\nlogger = gen_var.log\\n\\n\\ndef generate_date_range(start_date, end_date, inc_holidays=False):\\n    \\"\\"\\"\\n    Generate dates between start_date and end_date, skipping weekends and holidays.\\n    \\"\\"\\"\\n    if not inc_holidays:\\n        us_holidays = holidays.US(years=range(start_date.year, end_date.year + 1))\\n    elif inc_holidays == 'NYSE':\\n        us_holidays = holidays.NYSE(years=range(start_date.year, end_date.year + 1))\\n    else:\\n        us_holidays = []\\n    current_date = start_date\\n    while current_date <= end_date:\\n        # Skip weekends\\n        if current_date.weekday() in (5, 6):  # 5=Saturday, 6=Sunday\\n            current_date += timedelta(days=1)\\n            continue\\n\\n        # Skip US holidays\\n        if current_date in us_holidays:\\n            current_date += timedelta(days=1)\\n            continue\\n\\n        yield current_date.strftime(\\"%Y-%m-%d\\")\\n        current_date += timedelta(days=1)\\n\\n\\ndef date_intervals(final=datetime.today(), first=datetime(1900, 1, 1), batch_size=3 * 30):\\n    end_date = final\\n    start_date = end_date - timedelta(days=batch_size)  # Approximation of 6 months as 30 days per month\\n\\n    # Generate list of date ranges\\n    date_ranges = []\\n    while end_date > first:\\n        date_ranges.append([start_date, end_date])\\n        end_date = start_date - timedelta(days=1)\\n        start_date = end_date - timedelta(days=batch_size)\\n\\n    return date_ranges\\n\\n\\nasync def fetch_data(session, url, date=None, timeout=20, retries=2, retry_delay=3):\\n    \\"\\"\\"\\n    Fetch data asynchronously for a specific date or a general URL.\\n    \\"\\"\\"\\n    response = None\\n    for attempt in range(1, retries + 1):\\n        try:\\n            response = await session.get(url, timeout=timeout)\\n            response.raise_for_status()\\n            gen_var.wait_tasks += 1\\n            return date, url, response.json()  # Return immediately if successful\\n        except httpx.TimeoutException:\\n            logger.error(f\\"Timeout occurred for {date if date else url} (Attempt {attempt}/{retries}).\\")\\n        except httpx.RequestError as e:\\n            logger.error(f\\"Connection error for {date if date else url} (Attempt {attempt}/{retries}): {e}\\")\\n        except httpx.HTTPError as e:\\n            logger.error(f\\"HTTP error for {date if date else url}: {e}\\")\\n            gen_var.wait_tasks += 1\\n            break  # No retry for HTTP status errors (e.g., 404, 500)\\n\\n        if attempt < retries:\\n            logger.info(f\\"Retrying in {retry_delay} seconds...\\")\\n            await asyncio.sleep(retry_delay)\\n        else:\\n            logger.warning(f\\"All retries failed for {date if date else shorterns(url)}.\\")\\n\\n        # If all attempts fail\\n    return date, url, None\\n\\n\\n\\nasync def fetch_all_data(api_url_template, ticker, start_date, end_date, api_key, filled_dates):\\n    \\"\\"\\"\\n    Fetch all data asynchronously within the date range with URL logging.\\n    \\"\\"\\"\\n    tasks = []\\n    async with httpx.AsyncClient() as session:\\n        for d in generate_date_range(start_date, end_date, inc_holidays='NYSE'):\\n            if datetime.strptime(d, '%Y-%m-%d').date() in filled_dates:\\n                logger.info(\\"Skipping {d}, already filled.\\", {\\"d\\": d})\\n            else:\\n                url = api_url_template.format(ticker, d, d, api_key)\\n                tasks.append(fetch_data(session, url, d, retries=gen_var.max_retries, retry_delay=gen_var.retry_delay))\\n\\n        # Process tasks as they complete\\n        results = []\\n        for task in asyncio.as_completed(tasks):\\n            try:\\n                date, url, data = await task\\n                logger.info(\\"Fetched data from {url}\\", {\\"url\\": url})\\n                if data is not None:\\n                    results.append([date, ticker, url, json.dumps(data)])\\n            except Exception as e:\\n                logger.error(f\\"Error during task execution: {e}\\")\\n\\n    return results\\n\\n\\ndef main(ticker, ranger):\\n    \\"\\"\\"\\n    Main function to handle data fetching and database insertion.\\n    \\"\\"\\"\\n    schema = \\"finmo_prep\\"\\n    api_key = API_KMONGER.get(alias='finmo')[0]['key']\\n    table_name = f'{ticker}_bulk'\\n\\n    # Date Range\\n    start_date = ranger[0]\\n    end_date = ranger[1]\\n\\n    # Database Configuration\\n    db_conn = CREDENTIALS_MONGER.get(name='khzz_stocks_api')[0]\\n    db_config = {\\n        \\"dbname\\": db_conn['Database'],\\n        \\"user\\": db_conn['Uid'],\\n        \\"password\\": db_conn['Pwd'],\\n        \\"host\\": db_conn['Server'],\\n        \\"port\\": db_conn['Port'],\\n    }\\n\\n    # Connect to PostgreSQL\\n    conn = psycopg.connect(**db_config)\\n    logger.info(\\"Connected to PostgreSQL.\\")\\n    with conn as conn:\\n        if not gen_var.table_exists:\\n            if not check_table_exists(conn, schema, table_name):\\n                logger.info(f\\"Table {schema}.{table_name} does not exist. Creating it.\\")\\n                execute_schema(conn, schema=schema, table_name=table_name)\\n                logger.info(f\\"Table {schema}.{table_name} created.\\")\\n            else:\\n                logger.info(f\\"Table {schema}.{table_name} exists.\\")\\n            gen_var.table_exists = True\\n\\n        filled_dates = dates_from_db.get(conn, schema, table_name)\\n\\n        try:\\n            # Fetch data asynchronously\\n            results = asyncio.run(fetch_all_data(api_endpoint, ticker, start_date, end_date, api_key, filled_dates))\\n\\n            # Insert data into PostgreSQL\\n            if results:\\n                batch_insert_into_table(conn, schema, table_name, results)\\n                logger.info(\\"Inserted {n} rows into {w}.\\", {\\"n\\": len(results), \\"w\\": f'{schema}.{table_name}'})\\n            else:\\n                logger.info(\\"No new data to insert.\\")\\n\\n        except Exception as e:\\n            logger.error(f\\"Error in main: {e}\\")\\n        finally:\\n            conn.close()\\n            logger.info(\\"PostgreSQL connection closed.\\")\\n\\n\\ndef iteration():\\n    try:\\n        for r in date_intervals(gen_var.LAST_TIME, gen_var.FIRST_TIME, batch_size=4 * 30):\\n            try:\\n                main(gen_var.ticker_symbol, r)  # Process the batch\\n                wait_time = gen_var.wait_tasks * gen_var.wait_gain\\n                # Update user feedback and wait time\\n                logger.info('Iteration {iteration} done, waiting {wait_time} seconds',\\n                            {\\"iteration\\": \\"#\\" + str(gen_var.STARTING), \\"wait_time\\": wait_time})\\n                logger.info('FROM {d1} TO {d2}', {\\"d1\\": r[0], \\"d2\\": r[1]})\\n\\n                # Increment iteration counter\\n                gen_var.STARTING += 1\\n\\n                # Pause for WAIT_TIME seconds\\n                time.sleep(wait_time)\\n                gen_var.wait_tasks = 0\\n\\n            except Exception as e:\\n                logger.error(f\\"Error in processing range {r}: {e}\\")\\n                print(f\\"Error during processing range {r}, skipping to next batch.\\")\\n                continue  # Skip to the next range if an error occurs\\n    except KeyboardInterrupt:\\n        logger.info(\\"Process interrupted by user.\\")\\n    except Exception as e:\\n        logger.error(f\\"Unexpected error in main loop: {e}\\")\\n    finally:\\n        logger.info(\\"Batch processing complete.\\")\\n\\n\\nif __name__ == \\"__main__\\":\\n    api_endpoint = gen_var.template_intraday_url\\n    # tickers_list = ['DIA', 'KO', 'IBM', 'AAPL', 'GS', 'HD', 'JNJ', 'VZ', 'T', 'NSC', 'BLK', 'C', 'JPM']\\n    tickers_list = get(gen_var.ITERATIONS)[0]\\n    print(tickers_list)\\n    for each in tickers_list:\\n        gen_var.table_exists = False\\n        gen_var.ticker_symbol = each\\n        iteration()\\n", "end_line": 214, "start_line": 1, "total_lines": 214}	f	2026-09-19 20:35:19.670329-04
