1127	chat-e233fdc6-1471-4b85-af2e-1e621b27d05c	step-02	read_file	{"path": "D:\\\\LOCAL_Share\\\\Code Projects\\\\cors-dummy\\\\backend\\\\app\\\\main.py"}	{"ok": true, "path": "D:\\\\LOCAL_Share\\\\Code Projects\\\\cors-dummy\\\\backend\\\\app\\\\main.py", "size": 1844, "tool": "read_file", "sha256": "daa0d2a70312d8c6f67c5552550a085ca07db05024641a18b28a6d6dabc7d202", "content": "from fastapi import FastAPI, Depends, HTTPException\\nfrom fastapi.middleware.cors import CORSMiddleware\\nfrom fastapi.responses import JSONResponse\\nfrom sqlalchemy.orm import Session\\nfrom database import engine, SessionLocal\\nimport models, crud, schemas\\nimport uvicorn\\nimport importlib\\n\\n# Dependency to get a DB session\\ndef get_db():\\n    db = SessionLocal()\\n    try:\\n        yield db\\n    finally:\\n        db.close()\\n\\nmodels.Base.metadata.create_all(bind=engine)\\n\\napp = FastAPI()\\n\\n# Configure CORS\\norigins = [\\n    \\"localhost\\",\\n    \\"http://localhost\\",\\n    \\"http://127.0.0.1\\",\\n    \\"127.0.0.1\\",\\n    \\"127.0.0.1:80\\",\\n    \\"192.168.0.31\\",\\n    \\"http://192.168.0.31\\",\\n    \\"192.168.0.31:4173\\",\\n    \\"http://192.168.0.31:4173\\",\\n    \\"http://localhost:4173\\",  # Add your frontend URL here\\n    \\"http://localhost:4665\\",  # Add your frontend URL here\\n    \\"http://kh22.boga-dace.ts.net:4665\\"\\n]\\n\\napp.add_middleware(\\n    CORSMiddleware,\\n    allow_origins=['*'],\\n    allow_credentials=True,\\n    allow_methods=[\\"*\\"],\\n    allow_headers=[\\"*\\"],\\n)\\n@app.get(\\"/\\")\\ndef read_root():\\n    return {\\"Hello\\": \\"World\\"}\\n\\n@app.get(\\"/items/{item_id}\\", response_model=schemas.Item)\\ndef read_item(item_id: int, db: Session = Depends(get_db)):\\n    item = crud.get_item(db, item_id=item_id)\\n    if item is None:\\n        raise HTTPException(status_code=404, detail=\\"Item not found\\")\\n    return item\\n\\n@app.get(\\"/unique-values/{table_name}/{column_name}\\")\\ndef get_column_unique_values(table_name: str, column_name: str):\\n    module = importlib.import_module('dynamic-scripts')\\n    unique_values = module.get_unique_values(table_name, column_name)\\n    return {\\"table\\": table_name, \\"column\\": column_name, \\"unique_values\\": unique_values}\\n\\nif __name__ == \\"__main__\\":\\n    uvicorn.run(\\"main:app\\", port=15552, log_level=\\"info\\", workers=4)", "end_line": 63, "start_line": 1, "total_lines": 63}	f	2026-09-18 23:12:35.600488-04
