1499	chat-44b0e0ba-0234-4891-9ba8-59e33431b4c2	step-05	read_file	{"path": "D:\\\\LOCAL_Share\\\\Code Projects\\\\cors-dummy\\\\frontend\\\\src\\\\lib\\\\api.js"}	{"ok": true, "path": "D:\\\\LOCAL_Share\\\\Code Projects\\\\cors-dummy\\\\frontend\\\\src\\\\lib\\\\api.js", "size": 1343, "tool": "read_file", "sha256": "329daa88296293ab3a7f9757d3442f4b797d7dc54a19b513b008653acc8c1093", "content": "/**\\n * Minimal API client for the cors-dummy endpoint host.\\n * All requests go to /api/* (proxied to FastAPI in dev, same-origin in prod).\\n */\\n\\nconst BASE = '/api'\\n\\n/**\\n * Fetch JSON from the backend.\\n * @param {string} path - e.g. '/health', '/meta', '/echo'\\n * @param {object} [options] - { method, body }\\n * @returns {Promise<{status: number, data: any, duration: number}>}\\n */\\nexport async function request(path, { method = 'GET', body = null } = {}) {\\n  const opts = { method }\\n  if (body !== null && method !== 'GET') {\\n    opts.headers = { 'Content-Type': 'application/json' }\\n    opts.body = JSON.stringify(body)\\n  }\\n\\n  const t0 = performance.now()\\n  const res = await fetch(BASE + path, opts)\\n  const duration = Math.round(performance.now() - t0)\\n\\n  let data\\n  try {\\n    data = await res.json()\\n  } catch {\\n    data = null\\n  }\\n\\n  return { status: res.status, data, duration }\\n}\\n\\n/**\\n * Fetch backend health.\\n * @returns {Promise<{ok: boolean, status: number, data: any, duration: number}>}\\n */\\nexport async function getHealth() {\\n  const r = await request('/health')\\n  return { ...r, ok: r.status === 200 && r.data?.status === 'ok' }\\n}\\n\\n/**\\n * Fetch endpoint metadata (discovered modules + routes).\\n * @returns {Promise<{status: number, data: any, duration: number}>}\\n */\\nexport async function getMeta() {\\n  return request('/meta')\\n}\\n", "end_line": 50, "start_line": 1, "total_lines": 50}	t	2026-09-19 12:56:29.113699-04
