ecrets in settings\\nimport inspect\\nsrc = inspect.getsource(sys.modules['app.settings'])\\nassert 'postgres' not in src.lower(), 'Settings must not contain postgres references'\\nassert 'password' not in src.lower(), 'Settings must not contain password references'\\nprint('PASS: No hard-coded secrets in settings module')\\n\\n# Test 6: OriginDecision is structured (has to_dict)\\nd6 = c2.evaluate('http://localhost:4665')\\ndd = d6.to_dict()\\nassert dd['allowed'] == True\\nassert dd['reason_code'] == ALLOWED_EXPLICIT\\nassert 'detail' in dd\\nassert 'origin' in dd\\nprint(f'PASS: OriginDecision.to_dict() -> {dd}')\\n\\nprint()\\nprint('ALL 6 VERIFICATION CHECKS PASSED')\\n\\" 2>&1", "timeout_seconds": 30}	{"ok": true, "tool": "run_command", "summary": "Bulky evidence archived; compact metadata retained for live context.", "archived_original_evidence_id": 1215, "content_omitted_from_live_context": true}	f	2026-09-19 02:53:42.163918-04
