RD, f'FAIL: {d}'\\nprint(f'PASS 5: Dev mode wildcard -> ALLOWED_DEV_WILDCARD')\\n\\n# Test 4: CORS middleware config\\nassert c3.allowed_origins_for_cors_middleware() == ['*']\\nassert c3.allow_credentials() == False  # wildcard + credentials is invalid\\nprint(f'PASS 6: Dev mode middleware -> [\\\\\\"*\\\\\\"], credentials=False')\\n\\n# Test 5: Production middleware config\\nassert c2.allowed_origins_for_cors_middleware() == ['http://localhost:4665', 'https://app.example.com']\\nassert c2.allow_credentials() == True\\nprint(f'PASS 7: Production middleware -> explicit list, credentials=True')\\n\\n# Test 6: No hard-coded secrets in settings\\nimport inspect\\nsrc = inspect.getsource(sys.modules['app.settings'])\\nassert 'postgres' not in src.lower()\\nassert 'password' not in src.lower()\\nassert 'secret' not in src.lower()\\nprint(f'PASS 8: No secrets in settings source')\\n\\n# Test 7: Service registry loads from env\\nos.environ['SERVICE_REGISTRY'] = '[{\\\\\\"name\\\\\\":\\\\\\"test-svc\\\\\\",\\\\\\"base_url\\\\\\":\\\\\\"http://localhost:9999\\\\\\",\\\\\\"allowed_path_prefixes\\\\\\":[\\\\\\"/api\\\\\\"],\\\\\\"timeout_seconds\\\\\\":5.0}]'\\ns4 = AppSettings()\\nassert len(s4.service_registry) == 1\\nassert s4.service_registry[0].name == 'test-svc'\\nassert s4.service_registry[0].base_url == 'http://localhost:9999'\\nassert s4.service_registry[0].allowed_path_prefixes == ['/api']\\nassert s4.service_registry[0].timeout_seconds == 5.0\\nprint(f'PASS 9: Service registry loads from env JSON')\\n\\n# Test 8: Upstream bounds\\nassert s4.upstream_timeout_seconds == 10.0\\nassert s4.upstream_max_response_bytes == 1048576\\nprint(f'PASS 10: Upstream bounds have restrictive defaults')\\n\\nprint()\\nprint('=== ALL 10 DISCRIMINATING CHECKS PASSED ===')\\n\\"\\n", "timeout_seconds": 30}	{"ok": true, "tool": "run_command", "summary": "Bulky evidence archived; compact metadata retained for live context.", "archived_original_evidence_id": 1238, "content_omitted_from_live