1557	chat-c467de3f-d486-460c-8ddc-774ee34440cb	step-02	write_file	{"path": "D:\\\\LOCAL_Share\\\\Code Projects\\\\cors-dummy\\\\frontend\\\\src\\\\__tests__\\\\RequestRunner.test.js", "content": "/**\\n * Discriminating tests for RequestRunner.vue (GET/POST JSON request runner).\\n *\\n * The component calls request(path, { method, body }) from ../lib/api.js.\\n * We mock that module and assert the EXACT arguments passed, so the tests\\n * discriminate correct request formatting from incorrect:\\n *\\n *  - GET run  -> request called with body=null, no body textarea rendered\\n *  - POST run -> request called with the parsed JSON body object\\n *  - invalid JSON body -> \\"Invalid JSON body\\" error, request NOT called\\n *  - success  -> status, duration, and pretty-printed JSON body rendered\\n *  - failure (status >= 400) -> result marked with the \\"fail\\" class\\n *  - request throws -> exception message rendered as the error\\n *  - method switching resets path/body to the sensible defaults\\n */\\nimport { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'\\nimport { mount } from '@vue/test-utils'\\nimport RequestRunner from '../components/RequestRunner.vue'\\n\\nvi.mock('../lib/api.js', () => ({\\n  request: vi.fn(),\\n}))\\n\\nimport { request } from '../lib/api.js'\\n\\ndescribe('RequestRunner – GET/POST JSON request runner', () => {\\n  beforeEach(() => {\\n    vi.clearAllMocks()\\n  })\\n\\n  afterEach(() => {\\n    vi.restoreAllMocks()\\n  })\\n\\n  it('sends a GET request with a null body and renders the response', async () => {\\n    request.mockResolvedValueOnce({\\n      status: 200,\\n      data: { status: 'ok', service: 'cors-dummy' },\\n      duration: 8,\\n    })\\n\\n    const wrapper = mount(RequestRunner)\\n\\n    // Default method is GET; body textarea must NOT be present for GET.\\n    expect(wrapper.find('.body-input').exists()).toBe(false)\\n\\n    await wrapper.find('.btn-run').trigger('click')\\n    await vi.waitFor(() => {\\n      expect(wrapper.find('.result').exists()).toBe(true)\\n    })\\n\\n    // Discriminating: request called with GET and a null body.\\n    expect(request).toHaveBeenCalledTimes(1)\\n    const [path, opts] = request.mock.calls[0]\\n    expect(path).toBe('/health')\\n    expect(opts.method).toBe('GET')\\n    expect(opts.body).toBeNull()\\n\\n    // Response rendered: status, duration, pretty JSON.\\n    expect(wrapper.find('.status-code').text()).toBe('200')\\n    expect(wrapper.find('.duration').text()).toBe('8ms')\\n    const bodyText = wrapper.find('.result-body').text()\\n    expect(bodyText).toContain('\\"status\\": \\"ok\\"')\\n    expect(bodyText).toContain('\\"service\\": \\"cors-dummy\\"')\\n    // Success styling.\\n    expect(wrapper.find('.result').classes()).toContain('ok')\\n  })\\n\\n  it('sends a POST request with the parsed JSON body object', async () => {\\n    request.mockResolvedValueOnce({\\n      status: 200,\\n      data: { echoed: { hello: 'world' } },\\n      duration: 15,\\n    })\\n\\n    const wrapper = mount(RequestRunner)\\n\\n    // Switch to POST.\\n    const postBtn = wrapper.findAll('.method-btn').find(b => b.text() === 'POST')\\n    await postBtn.trigger('click')\\n\\n    // Body textarea now present, pre-filled with the default sample.\\n    expect(wrapper.find('.body-input').exists()).toBe(true)\\n\\n    await wrapper.find('.btn-run').trigger('click')\\n    await vi.waitFor(() => {\\n      expect(wrapper.find('.result').exists()).toBe(true)\\n    })\\n\\n    // Discriminating: request called with POST and the PARSED body object.\\n    expect(request).toHaveBeenCalledTimes(1)\\n    const [path, opts] = request.mock.calls[0]\\n    expect(path).toBe('/echo')\\n    expect(opts.method).toBe('POST')\\n    expect(opts.body).toEqual({ hello: 'world' })\\n\\n    expect(wrapper.find('.status-code').text()).toBe('200')\\n    expect(wrapper.find('.result-body').text()).toContain('\\"echoed\\"')\\n  })\\n\\n  it('rejects an invalid JSON body without calling request', async () => {\\n    const wrapper = mount(RequestRunner)\\n\\n    const postBtn = wrapper.findAll('.method-btn').find(b => b.text() === 'POST')\\n    await postBtn.trigger('click')\\n\\n    // Set an invalid JSON body.\\n    const bodyInput = wrapper.find('.body-input')\\n    await bodyInput.setValue('{not valid json')\\n\\n    await wrapper.find('.btn-run').trigger('click')\\n    await vi.waitFor(() => {\\n      expect(wrapper.find('.result.error').exists()).toBe(true)\\n    })\\n\\n    // Discriminating: the error is shown AND no request was made.\\n    expect(wrapper.find('.result.error').text()).toBe('Invalid JSON body')\\n    expect(request).not.toHaveBeenCalled()\\n    // No success/failure result block.\\n    expect(wrapper.find('.result.ok').exists()).toBe(false)\\n    expect(wrapper.find('.result.fail').exists()).toBe(false)\\n  })\\n\\n  it('marks the result with the fail class when the status is >= 400', async () => {\\n    request.mockResolvedValueOnce({\\n      status: 404,\\n      data: { detail: 'Not Found' },\\n      duration: 3,\\n    })\\n\\n    const wrapper = mount(RequestRunner)\\n    await wrapper.find('.btn-run').trigger('click')\\n    await vi.waitFor(() => {\\n      expect(wrapper.find('.result').exists()).toBe(true)\\n    })\\n\\n    expect(wrapper.find('.status-code').text()).toBe('404')\\n    expect(wrapper.find('.result').classes()).toContain('fail')\\n    expect(wrapper.find('.result').classes()).not.toContain('ok')\\n  })\\n\\n  it('renders the exception message when request throws', async () => {\\n    request.mockRejectedValueOnce(new Error('connection refused'))\\n\\n    const wrapper = mount(RequestRunner)\\n    await wrapper.find('.btn-run').trigger('click')\\n    await vi.waitFor(() => {\\n      expect(wrapper.find('.result.error').exists()).toBe(true)\\n    })\\n\\n    expect(wrapper.find('.result.error').text()).toBe('connection refused')\\n    expect(wrapper.find('.result.ok').exists()).toBe(false)\\n    expect(wrapper.find('.result.fail').exists()).toBe(false)\\n  })\\n\\n  it('resets path and body to sensible defaults when switching methods', async () => {\\n    const wrapper = mount(RequestRunner)\\n\\n    // Start on GET: path should be /health, no body.\\n    expect(wrapper.find('.path-input').element.value).toBe('/health')\\n\\n    // Switch to POST: path -> /echo, body pre-filled.\\n    const postBtn = wrapper.findAll('.method-btn').find(b => b.text() === 'POST')\\n    await postBtn.trigger('click')\\n    expect(wrapper.find('.path-input').element.value).toBe('/echo')\\n    expect(wrapper.find('.body-input').element.value).toBe('{\\"hello\\": \\"world\\"}')\\n\\n    // Switch back to GET: path -> /health, body cleared.\\n    const getBtn = wrapper.findAll('.method-btn').find(b => b.text() === 'GET')\\n    await getBtn.trigger('click')\\n    expect(wrapper.find('.path-input').element.value).toBe('/health')\\n    expect(wrapper.find('.body-input').exists()).toBe(false)\\n  })\\n\\n  it('marks the active method button with the active class', async () => {\\n    const wrapper = mount(RequestRunner)\\n\\n    const getBtn = wrapper.findAll('.method-btn').find(b => b.text() === 'GET')\\n    const postBtn = wrapper.findAll('.method-btn').find(b => b.text() === 'POST')\\n\\n    // GET is the default active method.\\n    expect(getBtn.classes()).toContain('active')\\n    expect(postBtn.classes()).not.toContain('active')\\n\\n    await postBtn.trigger('click')\\n    expect(postBtn.classes()).toContain('active')\\n    expect(getBtn.classes()).not.toContain('active')\\n  })\\n})\\n"}	{"ok": true, "path": "D:\\\\LOCAL_Share\\\\Code Projects\\\\cors-dummy\\\\frontend\\\\src\\\\__tests__\\\\RequestRunner.test.js", "tool": "write_file", "bytes": 7003, "sha256": "5f1c65c8cb491a65f295ff9a89371c5a8edc58ede2c8beb79fca8f493d66eff4", "created": true}	f	2026-09-19 16:26:00.739255-04
