1565	chat-c467de3f-d486-460c-8ddc-774ee34440cb	step-02	read_file	{"path": "D:\\\\LOCAL_Share\\\\Code Projects\\\\cors-dummy\\\\frontend\\\\src\\\\__tests__\\\\HealthBadge.test.js"}	{"ok": true, "path": "D:\\\\LOCAL_Share\\\\Code Projects\\\\cors-dummy\\\\frontend\\\\src\\\\__tests__\\\\HealthBadge.test.js", "size": 3979, "tool": "read_file", "sha256": "0071fd4422c5148bcda93cb49dd95de44fc529f96896807d70bc5f163969af9e", "content": "/**\\n * Discriminating tests for HealthBadge.vue (health state).\\n *\\n * The component calls getHealth() from ../lib/api.js on mount and on refresh.\\n * We mock that module so the tests are deterministic and discriminating:\\n *  - ok response  -> status \\"ok\\", label \\"healthy\\", dot.ok, service detail, duration\\n *  - non-ok       -> status \\"error\\", label \\"unreachable\\", \\"HTTP <status>\\" detail\\n *  - thrown error -> status \\"error\\", label \\"unreachable\\", exception message detail\\n *  - refresh button re-invokes the check\\n */\\nimport { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'\\nimport { mount } from '@vue/test-utils'\\nimport HealthBadge from '../components/HealthBadge.vue'\\n\\nvi.mock('../lib/api.js', () => ({\\n  getHealth: vi.fn(),\\n}))\\n\\n// Import the mocked function AFTER vi.mock so we can control its return value.\\nimport { getHealth } from '../lib/api.js'\\n\\ndescribe('HealthBadge – health state', () => {\\n  beforeEach(() => {\\n    vi.clearAllMocks()\\n  })\\n\\n  afterEach(() => {\\n    vi.restoreAllMocks()\\n  })\\n\\n  it('shows healthy state, service detail, and duration on an ok response', async () => {\\n    getHealth.mockResolvedValueOnce({\\n      ok: true,\\n      status: 200,\\n      data: { status: 'ok', service: 'cors-dummy' },\\n      duration: 12,\\n    })\\n\\n    const wrapper = mount(HealthBadge)\\n    await vi.waitFor(() => {\\n      expect(wrapper.find('.label').text()).toBe('healthy')\\n    })\\n\\n    // Dot carries the \\"ok\\" class.\\n    expect(wrapper.find('.dot').classes()).toContain('ok')\\n    // Detail shows the service name from the payload.\\n    expect(wrapper.find('.detail').text()).toBe('cors-dummy')\\n    // Duration is rendered.\\n    expect(wrapper.find('.ms').text()).toBe('12ms')\\n    // getHealth was called exactly once on mount.\\n    expect(getHealth).toHaveBeenCalledTimes(1)\\n  })\\n\\n  it('falls back to the default service name when data.service is absent', async () => {\\n    getHealth.mockResolvedValueOnce({\\n      ok: true,\\n      status: 200,\\n      data: { status: 'ok' },\\n      duration: 5,\\n    })\\n\\n    const wrapper = mount(HealthBadge)\\n    await vi.waitFor(() => {\\n      expect(wrapper.find('.label').text()).toBe('healthy')\\n    })\\n\\n    expect(wrapper.find('.detail').text()).toBe('cors-dummy')\\n  })\\n\\n  it('shows unreachable state with HTTP status detail on a non-ok response', async () => {\\n    getHealth.mockResolvedValueOnce({\\n      ok: false,\\n      status: 503,\\n      data: null,\\n      duration: 30,\\n    })\\n\\n    const wrapper = mount(HealthBadge)\\n    await vi.waitFor(() => {\\n      expect(wrapper.find('.label').text()).toBe('unreachable')\\n    })\\n\\n    expect(wrapper.find('.dot').classes()).toContain('error')\\n    expect(wrapper.find('.detail').text()).toBe('HTTP 503')\\n    expect(wrapper.find('.ms').text()).toBe('30ms')\\n  })\\n\\n  it('shows unreachable state with the exception message when getHealth throws', async () => {\\n    getHealth.mockRejectedValueOnce(new Error('network down'))\\n\\n    const wrapper = mount(HealthBadge)\\n    await vi.waitFor(() => {\\n      expect(wrapper.find('.label').text()).toBe('unreachable')\\n    })\\n\\n    expect(wrapper.find('.dot').classes()).toContain('error')\\n    expect(wrapper.find('.detail').text()).toBe('network down')\\n  })\\n\\n  it('re-checks when the refresh button is clicked', async () => {\\n    // First mount call.\\n    getHealth.mockResolvedValueOnce({ ok: true, status: 200, data: { status: 'ok', service: 'cors-dummy' }, duration: 1 })\\n    const wrapper = mount(HealthBadge)\\n    await vi.waitFor(() => {\\n      expect(wrapper.find('.label').text()).toBe('healthy')\\n    })\\n    expect(getHealth).toHaveBeenCalledTimes(1)\\n\\n    // Second call via refresh button.\\n    getHealth.mockResolvedValueOnce({ ok: false, status: 500, data: null, duration: 2 })\\n    await wrapper.find('.btn-refresh').trigger('click')\\n    await vi.waitFor(() => {\\n      expect(wrapper.find('.label').text()).toBe('unreachable')\\n    })\\n    expect(getHealth).toHaveBeenCalledTimes(2)\\n    expect(wrapper.find('.detail').text()).toBe('HTTP 500')\\n  })\\n})\\n", "end_line": 118, "start_line": 1, "total_lines": 118}	t	2026-09-19 16:27:44.099654-04
