1646	chat-f70ef80b-5387-422a-83da-fe212221217a	step-03	read_file	{"path": "D:\\\\LOCAL_Share\\\\Code Projects\\\\boost-python-sql\\\\finmo_crawl\\\\async_batch_get.py"}	{"ok": true, "path": "D:\\\\LOCAL_Share\\\\Code Projects\\\\boost-python-sql\\\\finmo_crawl\\\\async_batch_get.py", "size": 4665, "tool": "read_file", "sha256": "63151e7a06d6fefadda34fe17641addc1ec679da02b96918ed173faa2e5be736", "content": "import asyncio\\nimport pandas as pd\\nimport httpx\\nfrom batch_verify_helpers import *\\nfrom init_variables import *\\nfrom functools import partial\\nimport asyncio\\n\\n\\nasync def run_blocking(func, *args, **kwargs):\\n    \\"\\"\\"\\n    Run a blocking function in the default thread pool, returning its result.\\n    \\"\\"\\"\\n    loop = asyncio.get_running_loop()\\n    return await loop.run_in_executor(\\n        None,  # None => use default ThreadPoolExecutor\\n        lambda: func(*args, **kwargs)\\n    )\\n\\n\\nasync def process_ticker_batch_async(ticker_batch, batch_number, total_batches):\\n    \\"\\"\\"\\n    Asynchronously process a batch of tickers:\\n      - Make HTTP requests via httpx.AsyncClient.\\n      - Use run_in_executor to handle blocking DB operations so as not to block the event loop.\\n    \\"\\"\\"\\n    print(f\\"\\\\nStarting batch {batch_number}/{total_batches}\\")\\n    schema = 'daily'\\n    results = []\\n\\n    # Use an async client for non-blocking I/O requests\\n    async with httpx.AsyncClient() as client:\\n        # For each ticker in the batch\\n        for single_ticker in ticker_batch:\\n            ticker = single_ticker[0]\\n            daily_endpoint = (\\n                f'https://financialmodelingprep.com/api/v3/historical-price-full/{ticker}'\\n                f'?from=1980-10-10&apikey={finmo_key}'\\n            )\\n            table_name = f'{ticker}_daily'\\n\\n            # Check if table exists (blocking). We'll do it in an executor:\\n            table_exists = await run_blocking(verify_table, table_name, schema=schema, connection=target_db)\\n            if table_exists:\\n                results.append(f\\"Skipping {ticker} because table already exists.\\")\\n                continue\\n\\n            # HTTP GET request (async)\\n            try:\\n                response = await client.get(daily_endpoint, timeout=12.5)\\n                response.raise_for_status()\\n            except Exception as e:\\n                results.append(f\\"HTTP error for {ticker}: {e}\\")\\n                continue\\n\\n            # Process data and do DB inserts (blocking)\\n            try:\\n                # 1) Create the table if not exists\\n                create_sql = f'''\\n                    CREATE TABLE IF NOT EXISTS {schema}.\\"{table_name}\\" (\\n                        date             TIMESTAMP PRIMARY KEY NOT NULL,\\n                        open             DECIMAL(16, 4),\\n                        high             DECIMAL(16, 4),\\n                        low              DECIMAL(16, 4),\\n                        close            DECIMAL(16, 4),\\n                        adjclose         DECIMAL(16, 4),\\n                        volume           BIGINT,\\n                        unadjustedvolume BIGINT,\\n                        price_change     DOUBLE PRECISION,\\n                        changepercent    DOUBLE PRECISION,\\n                        vwap             DOUBLE PRECISION,\\n                        changeovertime   DOUBLE PRECISION\\n                    )\\n                '''\\n                await run_blocking(target_db.cursor().execute, create_sql)\\n\\n                # 2) Convert response to DataFrame\\n                data = response.json()['historical']\\n                g = pd.DataFrame(data)\\n                g['date'] = pd.to_datetime(g['date'])\\n                g.set_index(['date'], inplace=True)\\n                if 'label' in g.columns:\\n                    g.drop(columns=['label'], inplace=True)\\n\\n                # 3) Prepare inserts\\n                insert_sql = f'''\\n                    INSERT INTO {schema}.\\"{table_name}\\" ({table_columns_str})\\n                    VALUES ({table_placeholders_str})\\n                '''\\n                data_tuples = [\\n                    (\\n                        idx,\\n                        row.get(\\"open\\"), row.get(\\"high\\"), row.get(\\"low\\"),\\n                        row.get(\\"close\\"), row.get(\\"adjClose\\"), row.get(\\"volume\\"),\\n                        row.get(\\"unadjustedVolume\\"), row.get(\\"change\\"),\\n                        row.get(\\"changePercent\\"), row.get(\\"vwap\\"), row.get(\\"changeOverTime\\")\\n                    )\\n                    for idx, row in g.iterrows()\\n                ]\\n\\n                # 4) Execute the batch insert\\n                def do_db_inserts():\\n                    with target_db.cursor() as cur:\\n                        cur.executemany(insert_sql, data_tuples)\\n                        target_db.commit()\\n\\n                await run_blocking(do_db_inserts)\\n                results.append(f\\"Successfully wrote {schema}.{table_name}\\")\\n\\n            except Exception as e:\\n                results.append(f\\"Database error for {ticker}: {e}\\")\\n\\n    return results\\n", "end_line": 113, "start_line": 1, "total_lines": 113}	f	2026-09-19 20:34:15.717243-04
