1656	chat-f70ef80b-5387-422a-83da-fe212221217a	step-03	read_file	{"path": "D:\\\\LOCAL_Share\\\\Code Projects\\\\boost-python-sql\\\\finmo_crawl\\\\_xx_try_new_part.py"}	{"ok": true, "path": "D:\\\\LOCAL_Share\\\\Code Projects\\\\boost-python-sql\\\\finmo_crawl\\\\_xx_try_new_part.py", "size": 2361, "tool": "read_file", "sha256": "58a7dd1767ecb9ecbb16ffb6bdc5369a6dd6b8dd2b01a3f753df466146067cd9", "content": "import psycopg\\nfrom datetime import datetime\\n\\ndef ensure_partition_exists(conn, schema, table_name, year):\\n    \\"\\"\\"\\n    Ensure a partition exists for the given year in the partitioned table.\\n    If it doesn't exist, create it.\\n    \\"\\"\\"\\n    partition_name = f\\"{table_name}_{year}\\"\\n    check_partition_query = \\"\\"\\"\\n    SELECT child.relname AS partition_name\\n    FROM pg_inherits\\n    JOIN pg_class child ON pg_inherits.inhrelid = child.oid\\n    JOIN pg_class parent ON pg_inherits.inhparent = parent.oid\\n    JOIN pg_namespace ns ON ns.oid = child.relnamespace\\n    WHERE parent.relname = %s\\n    AND nspname = %s\\n    AND child.relname = %s;\\n    \\"\\"\\"\\n    create_partition_query = f\\"\\"\\"\\n    CREATE TABLE \\"{schema}\\".\\"{partition_name}\\" PARTITION OF \\"{schema}\\".\\"{table_name}\\"\\n    FOR VALUES FROM ('{year}-01-01') TO ('{year + 1}-01-01');\\n    \\"\\"\\"\\n    with conn.cursor() as cur:\\n        # Check if the partition exists\\n        cur.execute(check_partition_query, (table_name, schema, partition_name))\\n        if not cur.fetchone():\\n            # Partition doesn't exist, create it\\n            print(f\\"Creating partition {partition_name}...\\")\\n            cur.execute(create_partition_query)\\n            conn.commit()\\n            print(f\\"Partition {partition_name} created.\\")\\n        else:\\n            print(f\\"Partition {partition_name} already exists.\\")\\n\\ndef insert_data(conn, schema, table_name, data):\\n    \\"\\"\\"\\n    Insert data into a partitioned table, ensuring partitions exist as needed.\\n    \\"\\"\\"\\n    for row in data:\\n        date = row[0]  # Assuming the first column is a date\\n        year = datetime.strptime(date, \\"%Y-%m-%d\\").year\\n        ensure_partition_exists(conn, schema, table_name, year)\\n        # Insert the row\\n        query = f'INSERT INTO \\"{schema}\\".\\"{table_name}\\" VALUES (%s, %s, %s)'\\n        with conn.cursor() as cur:\\n            cur.execute(query, row)\\n    conn.commit()\\n\\n# Example usage\\ndb_config = {\\n    \\"dbname\\": \\"your_db\\",\\n    \\"user\\": \\"your_user\\",\\n    \\"password\\": \\"your_password\\",\\n    \\"host\\": \\"your_host\\",\\n    \\"port\\": \\"your_port\\",\\n}\\n\\nconn = psycopg.connect(**db_config)\\nschema = \\"public\\"\\ntable_name = \\"partitioned_table\\"\\n\\n# Example data\\ndata = [\\n    (\\"2023-06-15\\", \\"value1\\", \\"value2\\"),\\n    (\\"2024-03-22\\", \\"value3\\", \\"value4\\"),\\n]\\n\\ninsert_data(conn, schema, table_name, data)\\nconn.close()\\n", "end_line": 70, "start_line": 1, "total_lines": 70}	f	2026-09-19 20:34:33.782539-04
