"horizontal_gridline\\", \\"y\\": 642, \\"price\\": 704.0},\\n    {\\"id\\": \\"grid-702\\", \\"type\\": \\"horizontal_gridline\\", \\"y\\": 764, \\"price\\": 702.0},\\n    {\\"id\\": \\"grid-700\\", \\"type\\": \\"horizontal_gridline\\", \\"y\\": 887, \\"price\\": 700.0}\\n  ],\\n  \\"data_objects_summary\\": {\\n    \\"total_objects\\": 16,\\n    \\"broad_color_fills\\": 5,\\n    \\"thin_vertical_traces\\": 10,\\n    \\"color_distribution\\": {\\"red\\": {\\"fills\\": 3, \\"traces\\": 7}, \\"green\\": {\\"fills\\": 1, \\"traces\\": 2}, \\"blue\\": {\\"fills\\": 1, \\"traces\\": 1}},\\n    \\"primary_pane\\": {\\"top_y\\": 154, \\"bottom_y\\": 887, \\"width_px\\": 1217},\\n    \\"pixel_to_price\\": \\"price = 700.00 + (887 - y) / 61.083\\",\\n    \\"px_per_price_unit\\": 61.083,\\n    \\"price_units_per_px\\": 0.0164\\n  },\\n  \\"occlusion_summary\\": {\\n    \\"total_candidates\\": 10,\\n    \\"high_confidence\\": 6,\\n    \\"supported\\": 2,\\n    \\"uncertain\\": 2,\\n    \\"relationship_label\\": \\"thin_trace_continues_through_broad_same_color_fill\\",\\n    \\"vision_interpretation\\": \\"normal wick-over-body rendering (standard chart drawing)\\",\\n    \\"geometric_interpretation\\": \\"occlusion (trace behind fill, z=0 vs z=1)\\",\\n    \\"disagreement_scope\\": \\"semantic only; visual pattern is confirmed by both methods\\",\\n    \\"lowest_confidence_candidates\\": [1, 2, 10],\\n    \\"lowest_confidence_note\\": \\"These 3 candidates (y_end 833-840) are the sole source of the geometric-vision price disagreement; vision does not confirm them as visible wick tips\\"\\n  },\\n  \\"uncertainty\\": {\\n    \\"primary_source\\": \\"semantic ambiguity: wick tip vs fill/body bottom boundary\\",\\n    \\"secondary_source\\": \\"sub-gridline interpolation between 700.00 and 702.00\\",\\n    \\"tertiary_source\\": \\"JPEG compression artifacts (fraction 0.000846, negligible)\\",\\n    \\"pixel_localization_error\\": \\"±0.016 price units per pixel (negligible)\\"